declarations.code:
template <class Iter>

constexpr reverse_iterator<Iter> operator+

    (std::iter_difference_t<Iter> n, const reverse_iterator<Iter> &it);

examples.code:
#include <iostream>
#include <iterator>
#include <list>
#include <vector>

int main() {
    {
        std::vector v{0, 1, 2, 3};
        std::reverse_iterator<std::vector<int>::iterator> ri1{
            std::reverse_iterator{v.rbegin()}};
        std::cout << *ri1 << ' '; // 3
        std::reverse_iterator<std::vector<int>::iterator> ri2{2 + ri1};
        std::cout << *ri2 << ' '; // 1
    }

    {
        std::list l{5, 6, 7, 8};
        std::reverse_iterator<std::list<int>::iterator> ri1{
            std::reverse_iterator{l.rbegin()}};
        std::cout << *ri1 << '\n'; // 8
        //  auto ri2{2 + ri1}; // Error: the underlying iterator does not
        //        model random access iterator
    }
}
